import "sindarin-pkg-sdk/src/core/uuid"
@source "credits.c"
@alias "inspect_uuid_credit"
native fn credit(value: UUID): int
fn main(): void =>
  var dns: UUID = UUID.namespaceDns()
  println(credit(dns))
  var url: UUID = UUID.namespaceUrl()
  println(credit(url))
  var oid: UUID = UUID.namespaceOid()
  println(credit(oid))
  var x500: UUID = UUID.namespaceX500()
  println(credit(x500))
